  "a_sentences": [
    {
      "a_text": "Selon l'art. 117 CPC, la personne assurée a droit au gratuito patrocinio si elle est dépourvue des moyens nécessaires et si sa demande ne paraît pas dépourvue de chances de succès.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "L'avocat, en tant que mandataire, répond du dommage causé par la violation de ses obligations de diligence et de fidélité, mais les parties supportent le risque du procès et ne peuvent pas transférer ce risque à leur avocat.",
      "b_propositions": ["P2", "P3"]
    },
    {
      "a_text": "L'appréciation des chances de succès s'effectue à la date du dépôt de la demande sur la base d'un examen sommaire.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que les considérations de l'appel concernaient l'absence d'illustration du lien de causalité entre les violations contractuelles alléguées et le dommage prétendu.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "La juridiction cantonale a estimé que, à un examen sommaire, la demande de réparation ne présentait pas de chances de succès.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La juridiction cantonale a également jugé que la seconde demande en dommages-intérêts était dépourvue de probabilité de succès.",
      "b_propositions": ["P7"]
    }
  ]
}
